INSERT INTO profiles (id, user_id, first_name, last_name, age, gender, city, district, metro_station, minutes_to_metro, bio, photo_url) VALUES
('d1000000-0000-0000-0000-000000000001', 'd0000000-0000-0000-0000-000000000001', 'Дмитрий', 'Соколов', 26, 'male', 'Москва', 'Хамовники', 'Парк Культуры', 6, 'Люблю бег по утрам и джаз. Ищу спокойного и чистоплотного соседа.', '/media/0f9a6f86e2806b20e766fd3ae2897257.jpg'),
('d1000000-0000-0000-0000-000000000002', 'd0000000-0000-0000-0000-000000000002', 'Анна', 'Кузнецова', 23, 'female', 'Москва', 'Хамовники', 'Парк Культуры', 4, 'Дизайнер интерьеров, обожаю кофе и живопись. Дома тихо и уютно.', '/media/72beea79877602f2ec1967220986ba04.jpg'),
('d1000000-0000-0000-0000-000000000003', 'd0000000-0000-0000-0000-000000000003', 'Иван', 'Морозов', 29, 'male', 'Москва', 'Тверской', 'Маяковская', 5, 'Разработчик, вечером играю в настольные игры. Люблю готовить.', '/media/3a25d4c633cf0b4b8bb3af3adb91d9a4.jpg'),
('d1000000-0000-0000-0000-000000000004', 'd0000000-0000-0000-0000-000000000004', 'Мария', 'Петрова', 25, 'female', 'Москва', 'Тверской', 'Маяковская', 8, 'Фотограф, часто в разъездах. Люблю путешествия и искусство.', '/media/90dd7cb2ad56954bbaa07d1fddf1fe5e.jpg'),
('d1000000-0000-0000-0000-000000000005', 'd0000000-0000-0000-0000-000000000005', 'Сергей', 'Волков', 31, 'male', 'Москва', 'Басманный', 'Бауманская', 3, 'Работаю из дома. Тихий, аккуратный, без животных.', '/media/4f0e9319727ef9683e336110a5a05349.jpg'),
('d1000000-0000-0000-0000-000000000006', 'd0000000-0000-0000-0000-000000000006', 'Екатерина', 'Смирнова', 27, 'female', 'Москва', 'Басманный', 'Бауманская', 6, 'Готовлю и пою. Ищу соседа для долгой совместной аренды.', '/media/8be902ec9450bc7c19a36456c984d6d2.jpg'),
('d1000000-0000-0000-0000-000000000007', 'd0000000-0000-0000-0000-000000000007', 'Алексей', 'Новиков', 24, 'male', 'Москва', 'Пресненский', 'Улица 1905 года', 7, 'Кино, спорт и немного игр. Дружелюбный и без вредных привычек.', '/media/87e63dae76b36fe3de1f780f3330f54c.jpg'),
('d1000000-0000-0000-0000-000000000008', 'd0000000-0000-0000-0000-000000000008', 'Ольга', 'Морозова', 28, 'female', 'Москва', 'Пресненский', 'Выставочная', 9, 'Йога, книги и искусство. Ценю порядок и уважение к личному пространству.', '/media/c9d25b6d8931b8ede1e06e35f4146c59.jpg'),
('d1000000-0000-0000-0000-000000000009', 'd0000000-0000-0000-0000-000000000009', 'Никита', 'Орлов', 22, 'male', 'Москва', 'Сокол', 'Сокол', 5, 'Студент, не курю, часто в разъездах. Спокойный и ненавязчивый.', '/media/33408b603df7e97224129767a3543a46.jpg'),
('d1000000-0000-0000-0000-000000000010', 'd0000000-0000-0000-0000-000000000010', 'Татьяна', 'Захарова', 30, 'female', 'Москва', 'Сокол', 'Полежаевская', 12, 'Преподаю танцы, люблю музыку и активный отдых.', '/media/0102f6b0c194e0dc84f19a69a3871d05.jpg'),
('d1000000-0000-0000-0000-000000000011', 'd0000000-0000-0000-0000-000000000011', 'Роман', 'Лебедев', 33, 'male', 'Москва', 'Раменки', 'Ломоносовский проспект', 8, 'Аналитик. Спокойный, без животных, люблю читать и смотреть кино.', '/media/515c50352f4c4c0193185c0a158a9ee0.png'),
('d1000000-0000-0000-0000-000000000012', 'd0000000-0000-0000-0000-000000000012', 'Юлия', 'Виноградова', 26, 'female', 'Москва', 'Раменки', 'Раменки', 6, 'Люблю готовить и гулять по городу. Открытая и позитивная.', '/media/2ab19370b02abedfa2c92178b76b0b69.jpg'),
('d1000000-0000-0000-0000-000000000013', 'd0000000-0000-0000-0000-000000000013', 'Артём', 'Фёдоров', 28, 'male', 'Москва', 'Измайлово', 'Измайловская', 10, 'Велоспорт, концерты и настолки. Всегда рад гостям.', '/media/d142d78bba16551bc77e003fb13affb7.jpg'),
('d1000000-0000-0000-0000-000000000014', 'd0000000-0000-0000-0000-000000000014', 'Кристина', 'Белова', 24, 'female', 'Москва', 'Измайлово', 'Партизанская', 7, 'Рисую и читаю, люблю тишину и уютные вечера.', '/media/8cb9c6117fbd10c243e0143be64b9c4d.jpg'),
('d1000000-0000-0000-0000-000000000015', 'd0000000-0000-0000-0000-000000000015', 'Максим', 'Крылов', 27, 'male', 'Москва', 'Хорошёво-Мнёвники', 'Мнёвники', 11, 'Музыкант, играю на гитаре. Ищу соседа, который любит музыку.', '/media/eb26e63c95a7ef285341091cd50cb1d9.jpg'),
('d1000000-0000-0000-0000-000000000016', 'd0000000-0000-0000-0000-000000000016', 'Виктория', 'Ершова', 29, 'female', 'Москва', 'Хорошёво-Мнёвники', 'Хорошёвская', 9, 'Маркетолог. Люблю путешествия, кофе и хорошие книги.', '/media/ff7ce3d80bb0247a242316930fc80b08.png'),
('d1000000-0000-0000-0000-000000000017', 'd0000000-0000-0000-0000-000000000017', 'Павел', 'Дмитриев', 26, 'male', 'Санкт-Петербург', 'Невский', 'Маяковская', 4, 'Программист. Люблю кино, спорт и прогулки по набережной.', '/media/b7a2b753f806877037c9228ea8ca7166.jpg'),
('d1000000-0000-0000-0000-000000000018', 'd0000000-0000-0000-0000-000000000018', 'Ксения', 'Романова', 24, 'female', 'Санкт-Петербург', 'Невский', 'Владимирская', 6, 'Журналист. Книги, танцы и старый город.', '/media/873ffa39fb93a29309ee7724a56dd016.jpg'),
('d1000000-0000-0000-0000-000000000019', 'd0000000-0000-0000-0000-000000000019', 'Глеб', 'Соловьёв', 30, 'male', 'Санкт-Петербург', 'Петроградский', 'Петроградская', 5, 'Архитектор. Тихий, ценю порядок, гостей не жду.', '/media/aefda5413c7e3fcb3cf8d52c8ce22818.jpg'),
('d1000000-0000-0000-0000-000000000020', 'd0000000-0000-0000-0000-000000000020', 'Дарья', 'Комарова', 25, 'female', 'Санкт-Петербург', 'Петроградский', 'Чкаловская', 8, 'Дизайнер интерьера, люблю искусство и велосипед.', '/media/c669dd33eae0e259a5917dd0bcb9945a.jpg'),
('d1000000-0000-0000-0000-000000000021', 'd0000000-0000-0000-0000-000000000021', 'Егор', 'Фомин', 23, 'male', 'Санкт-Петербург', 'Московский', 'Московская', 3, 'Инженер. Спорт, игры и немного кино.', '/media/25d28a4b2409a998615ccbb3edf3eb23.jpg'),
('d1000000-0000-0000-0000-000000000022', 'd0000000-0000-0000-0000-000000000022', 'Полина', 'Тихонова', 27, 'female', 'Санкт-Петербург', 'Московский', 'Электросила', 10, 'Учусь готовить, обожаю животных и уютные вечера.', '/media/97a8dfbdecfdf8198664bb04e9e1a9ce.jpg');
