('a0000000-0000-0000-0000-000000000004', 'd0000000-0000-0000-0000-000000000004', 45000, 3, 80, '2026-12-01', 'Просторная комната в новой квартире на Красной Пресне, панорамные окна.', TRUE),
('a0000000-0000-0000-0000-000000000005', 'd0000000-0000-0000-0000-000000000005', 33000, 1, 38, '2026-11-05', 'Комната в студии на Соколе, идеально для одного человека.', FALSE),
('a0000000-0000-0000-0000-000000000006', 'd0000000-0000-0000-0000-000000000006', 36000, 2, 60, '2026-11-20', 'Комната в двушке на Невском проспекте, весь центр пешком.', TRUE),
