INSERT INTO messages (id, chat_id, sender_id, content, is_read) VALUES
('d8000000-0000-0000-0000-000000000001', 'd7000000-0000-0000-0000-000000000001', 'd0000000-0000-0000-0000-000000000001', 'Привет! Увидел(а) твою анкету — очень совпадаем по району. Как насчёт вместе поискать жильё?', TRUE),
('d8000000-0000-0000-0000-000000000002', 'd7000000-0000-0000-0000-000000000001', :'me', 'Привет! Да, я как раз в поиске. Давай обсудим детали.', TRUE),
('d8000000-0000-0000-0000-000000000003', 'd7000000-0000-0000-0000-000000000001', 'd0000000-0000-0000-0000-000000000001', 'Отлично! Тогда предлагаю завтра посмотреть квартиру.', FALSE),
('d8000000-0000-0000-0000-000000000004', 'd7000000-0000-0000-0000-000000000002', 'd0000000-0000-0000-0000-000000000002', 'Здравствуй! Понравилась твоя анкета. Во сколько обычно встаёшь и ложишься?', TRUE),
('d8000000-0000-0000-0000-000000000005', 'd7000000-0000-0000-0000-000000000002', :'me', 'Привет! Обычно встаю в 7, ложусь в 23. А ты?', TRUE),
('d8000000-0000-0000-0000-000000000006', 'd7000000-0000-0000-0000-000000000002', 'd0000000-0000-0000-0000-000000000002', 'Супер, по режиму мы похожи :)', FALSE),
('d8000000-0000-0000-0000-000000000007', 'd7000000-0000-0000-0000-000000000003', 'd0000000-0000-0000-0000-000000000003', 'Привет! Ты не против животных? У меня есть маленький кот.', TRUE),
('d8000000-0000-0000-0000-000000000008', 'd7000000-0000-0000-0000-000000000003', :'me', 'Привет! Не против, люблю животных. Сколько ему лет?', TRUE),
('d8000000-0000-0000-0000-000000000009', 'd7000000-0000-0000-0000-000000000003', 'd0000000-0000-0000-0000-000000000003', 'Это замечательно! Тогда созвонимся.', FALSE),
('d8000000-0000-0000-0000-000000000010', 'd7000000-0000-0000-0000-000000000004', 'd0000000-0000-0000-0000-000000000004', 'Привет! А ты работаешь из дома или в офис ездишь?', TRUE),
('d8000000-0000-0000-0000-000000000011', 'd7000000-0000-0000-0000-000000000004', :'me', 'Привет! Два дня из дома, остальное в офисе. А у тебя как?', TRUE),
('d8000000-0000-0000-0000-000000000012', 'd7000000-0000-0000-0000-000000000004', 'd0000000-0000-0000-0000-000000000004', 'Понятно, спасибо! Мне подходит такой график.', FALSE),
('d8000000-0000-0000-0000-000000000013', 'd7000000-0000-0000-0000-000000000005', 'd0000000-0000-0000-0000-000000000005', 'Привет! Очень близко по бюджету и району. Давай встретимся и посмотрим квартиру?', TRUE),
('d8000000-0000-0000-0000-000000000014', 'd7000000-0000-0000-0000-000000000005', :'me', 'Привет! Давай. В выходные свободен(а)?', TRUE),
('d8000000-0000-0000-0000-000000000015', 'd7000000-0000-0000-0000-000000000005', 'd0000000-0000-0000-0000-000000000005', 'Отлично, тогда до выходных!', FALSE),
('d8000000-0000-0000-0000-000000000016', 'd7000000-0000-0000-0000-000000000006', 'd0000000-0000-0000-0000-000000000006', 'Добрый день! Как ты относишься к гостям по выходным?', TRUE),
('d8000000-0000-0000-0000-000000000017', 'd7000000-0000-0000-0000-000000000006', :'me', 'Привет! Спокойно, иногда сами собираемся. Главное предупредить.', TRUE),
('d8000000-0000-0000-0000-000000000018', 'd7000000-0000-0000-0000-000000000006', 'd0000000-0000-0000-0000-000000000006', 'Хорошо, буду предупреждать заранее.', FALSE),
('d8000000-0000-0000-0000-000000000019', 'd7000000-0000-0000-0000-000000000007', 'd0000000-0000-0000-0000-000000000007', 'Привет! У нас схожие интересы — тоже люблю музыку и прогулки. Какой район тебе важнее?', TRUE),
('d8000000-0000-0000-0000-000000000020', 'd7000000-0000-0000-0000-000000000007', :'me', 'Привет! Мне важнее близость к метро. Ты смотришь центр?', TRUE),
('d8000000-0000-0000-0000-000000000021', 'd7000000-0000-0000-0000-000000000007', 'd0000000-0000-0000-0000-000000000007', 'Да, смотрю центр и ближе к метро.', FALSE),
('d8000000-0000-0000-0000-000000000022', 'd7000000-0000-0000-0000-000000000008', 'd0000000-0000-0000-0000-000000000008', 'Здравствуйте! Скажите, есть ли возможность заехать до конца месяца?', TRUE),
('d8000000-0000-0000-0000-000000000023', 'd7000000-0000-0000-0000-000000000008', :'me', 'Привет! Да, могу заехать в течение двух недель.', TRUE),
('d8000000-0000-0000-0000-000000000024', 'd7000000-0000-0000-0000-000000000008', 'd0000000-0000-0000-0000-000000000008', 'Отлично, тогда я готов(а) заехать пораньше.', FALSE),
('d8000000-0000-0000-0000-000000000025', 'd7000000-0000-0000-0000-000000000009', 'd0000000-0000-0000-0000-000000000009', 'Привет! А ты куришь? Для меня это важно.', TRUE),
('d8000000-0000-0000-0000-000000000026', 'd7000000-0000-0000-0000-000000000009', :'me', 'Привет! Нет, не курю и не люблю запах табака.', TRUE),
('d8000000-0000-0000-0000-000000000027', 'd7000000-0000-0000-0000-000000000009', 'd0000000-0000-0000-0000-000000000009', 'Спасибо, это важно. Тогда мы точно подойдём друг другу.', FALSE),
('d8000000-0000-0000-0000-000000000028', 'd7000000-0000-0000-0000-000000000010', 'd0000000-0000-0000-0000-000000000010', 'Привет! Давай созвонимся и обсудим условия аренды подробнее.', TRUE),
('d8000000-0000-0000-0000-000000000029', 'd7000000-0000-0000-0000-000000000010', :'me', 'Привет! Давай, напиши, когда удобно.', TRUE),
('d8000000-0000-0000-0000-000000000030', 'd7000000-0000-0000-0000-000000000010', 'd0000000-0000-0000-0000-000000000010', 'Хорошо, напишу ближе к вечеру.', FALSE);
